import js from "@eslint/js";
import eslintPluginPrettier from "eslint-plugin-prettier/recommended";
import globals from "globals";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tseslint from "typescript-eslint";

import quality from "./eslint-rules/index.cjs";

// Quality gates (quality/*) are installed by copying tested rule files from
// vibe-coding-toolkit, not by writing rules from scratch. Do not edit
// eslint-rules/*.cjs by hand; recopy them from the same toolkit revision
// instead. See docs/prompts/08-eslint-quality-gates-install.md.
const testFiles = [
  "**/*{.,-}{test,spec}.{js,jsx,ts,tsx,mjs,cjs,mts,cts}",
  "**/{__tests__,__mocks__,fixtures,mocks}/**/*.{js,jsx,ts,tsx,mjs,cjs,mts,cts}",
];

export default tseslint.config(
  {
    ignores: [
      "dist",
      ".output",
      ".vinxi",
      // Generated by the Lovable AI gateway package; do not edit or lint.
      "src/generated/**",
    ],
  },
  {
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    files: ["**/*.{ts,tsx}"],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      "no-restricted-imports": [
        "error",
        {
          paths: [
            {
              name: "server-only",
              message:
                "TanStack Start does not use the Next.js `server-only` package. Rename the module to `*.server.ts` or mark it with `@tanstack/react-start/server-only`.",
            },
          ],
        },
      ],
      "react-refresh/only-export-components": ["warn", { allowConstantExport: true }],
      "@typescript-eslint/no-unused-vars": "off",
    },
  },
  {
    // Quality gates, measured against this project's real shape.
    files: ["src/**/*.{ts,tsx}"],
    plugins: { quality },
    rules: {
      // 4 files currently over budget (sidebar.tsx, live-relay.server.ts,
      // use-live-voice.ts, GraphPanel.tsx) — see 09-file-size-refactor.md.
      "quality/max-lines": ["warn", { max: 350 }],
      // 10 pre-existing direct console calls outside the error-capture
      // adapter — baseline recorded 2026-11-20.
      "quality/no-direct-console": [
        "warn",
        { logger: "src/lib/error-capture.ts (wraps console.error)" },
      ],
      // Zero violations today: the Supabase client is never imported
      // directly from routes/ or components/. Keep this at "error" so a
      // regression is caught immediately.
      "quality/no-direct-data-access": [
        "error",
        {
          modules: [
            "@/integrations/supabase/client",
            "@/integrations/supabase/client.server",
          ],
          bindings: ["supabase"],
          layers: ["/src/routes/", "/src/components/"],
          extensions: [".tsx"],
        },
      ],
    },
  },
  {
    // The log adapter itself: it wraps console.error, so it has to call it
    // directly. This block must stay AFTER the block that turns the rule on.
    files: ["src/lib/error-capture.ts"],
    plugins: { quality },
    rules: {
      "quality/no-direct-console": "off",
    },
  },
  {
    // Same file-size budget for test files, measured separately.
    files: testFiles,
    plugins: { quality },
    rules: {
      "quality/max-lines": ["warn", { max: 350, includeTests: true }],
    },
  },
  {
    files: ["eslint-rules/**/*.cjs"],
    languageOptions: {
      sourceType: "commonjs",
      globals: { module: "readonly", require: "readonly" },
    },
    rules: {
      "@typescript-eslint/no-require-imports": "off",
    },
  },
  eslintPluginPrettier,
);
